import 'dart:async'; import 'package:slotbookingadmin/core/api/api_services.dart'; import '../models/slot_model.dart';
class SlotRemoteDatasource { final SlotApi _api=SlotApi(); SlotRemoteDatasource(); Stream<List<SlotModel>> watchSlotsForGround(String id,DateTime date) async* { while(true){ yield (await _api.list(id,date)).map(SlotModel.fromMap).toList(); await Future.delayed(const Duration(seconds:5)); } } Future<void> addSlot(SlotModel s)=>_api.create(s.toMap()); Future<void> bulkAddSlots(List<SlotModel>s)=>_api.bulk(s.map((e)=>e.toMap()).toList()); Future<void> updateSlotStatus(String id,String status)=>_api.update(id,status:status); Future<void> updateSlotPrice(String id,double price)=>_api.update(id,price:price); Future<void> deleteSlot(String id)=>_api.delete(id); }
